            <div className="mx-auto max-w-5xl px-4 py-6 sm:px-8">
                {back.kind === "studio" ? (
                    <Link
                        to="/styles"
                        className="text-muted-foreground hover:text-foreground inline-flex items-center gap-1 text-sm"
                    >
                        <ChevronLeft className="size-4"/> 视觉风格
                    </Link>
                ) : (
                    <Link
                        to="/p/$projectId/world"
                        params={{projectId: back.projectId}}
                        search={{tab: "styles"}}
                        className="text-muted-foreground hover:text-foreground inline-flex items-center gap-1 text-sm"
                    >
                        <ChevronLeft className="size-4"/> 世界
                    </Link>
                )}
                <h1 className="mt-3 text-lg font-semibold">风格</h1>
                <div className="mt-6 grid gap-8 lg:grid-cols-[1.1fr_0.9fr]">
                    <div className="grid grid-cols-2 gap-4">
                        {STYLE_SLOTS.map((slot) => (
                            <EditableGenerationSlot
                                unavailable={!loaded}
                                onEditorOpenChange={(open) => setOpenEditors(count => count + (open ? 1 : -1))}
                                key={slot.id}
                                projectId={style.projectId}
                                targetKey={JSON.stringify([style.projectId, "style", style.id, slot.id])}
                                label={slot.label}
                                title={`风格 · ${slot.label}`}
                                variant="asset"
                                slot={style.slots?.[slot.id]}
                                onSave={(value, baseline) => setStyleSlot(style.id, slot.id, value, baseline)}
                            />
                        ))}
                    </div>
                    <div className="space-y-4">
                        <AssetTextField
                            key={`${style.id}:name`}
                            draftKey={`${style.id}:name`}
                            label="名称"
                            value={style.name}
                            projectId={style.projectId}
                            persist={(value, baseline) => patchStyle(style.id, {name: value}, {name: baseline})}
                        />
                        <AssetTextField
                            key={`${style.id}:notes`}
                            draftKey={`${style.id}:notes`}
                            label="备注"
                            value={style.notes}
                            projectId={style.projectId}
                            persist={(value, baseline) => patchStyle(style.id, {notes: value}, {notes: baseline})}
                            multiline
                            placeholder="画风、光色、镜头气质"
                        />
                        <details className="rounded-xl border bg-card p-4">
                            <summary className="cursor-pointer text-sm font-medium">创作细节 · 选填</summary>
                            <p className="text-muted-foreground mt-2 text-xs leading-5">把色彩、光影与构图方向写清楚，作为整部作品的视觉依据。所有信息均为选填。</p>
                            <div className="mt-4 space-y-4">
                                <AssetTextField
                                    key={`${style.id}:palette`}
                                    draftKey={`${style.id}:palette`}
                                    label="色彩方案"
                                    value={style.palette ?? ""}
                                    projectId={style.projectId}
                                    persist={(value, baseline) => patchStyle(style.id, {palette: value}, {palette: baseline})}
                                    placeholder="主色、辅助色、饱和度与色彩关系"
                                    multiline
                                />
                                <AssetTextField
                                    key={`${style.id}:lighting`}
                                    draftKey={`${style.id}:lighting`}
                                    label="光影风格"
                                    value={style.lighting ?? ""}
                                    projectId={style.projectId}
                                    persist={(value, baseline) => patchStyle(style.id, {lighting: value}, {lighting: baseline})}
                                    placeholder="柔硬、反差、色温与阴影"
                                    multiline
                                />
                                <AssetTextField
                                    key={`${style.id}:lens`}
                                    draftKey={`${style.id}:lens`}
                                    label="镜头气质"
                                    value={style.lens ?? ""}
                                    projectId={style.projectId}
                                    persist={(value, baseline) => patchStyle(style.id, {lens: value}, {lens: baseline})}
                                    placeholder="焦段倾向、景深、畸变与颗粒"
                                    multiline
                                />
                                <AssetTextField
                                    key={`${style.id}:composition`}
                                    draftKey={`${style.id}:composition`}
                                    label="构图原则"
                                    value={style.composition ?? ""}
                                    projectId={style.projectId}
                                    persist={(value, baseline) => patchStyle(style.id, {composition: value}, {composition: baseline})}
                                    placeholder="画面重心、留白、对称与层次"
                                    multiline
                                />
                                <AssetTextField
                                    key={`${style.id}:negativePrompt`}
                                    draftKey={`${style.id}:negativePrompt`}
                                    label="避免出现"
                                    value={style.negativePrompt ?? ""}
                                    projectId={style.projectId}
                                    persist={(value, baseline) => patchStyle(style.id, {negativePrompt: value}, {negativePrompt: baseline})}
                                    placeholder="不希望出现的颜色、质感、构图或元素"
                                    multiline
                                />
                            </div>
                        </details>
                    </div>
                </div>
            </div>
        </div>
    );
}

import {useShotMedia} from "@/lib/useShotMedia";
import {Link} from "@tanstack/react-router";
import {useLiveQuery} from "dexie-react-hooks";
import {ArrowLeft, Printer} from "lucide-react";
import {MediaPreview} from "@/components/media/MediaThumb";
import {Button} from "@/components/ui/button";
import {db} from "@/db/database";
import {episodeLabel, normalizeProjectMode} from "@/domain/types";
import {deriveEpisodeDelivery} from "@/lib/episodeDelivery";
import {formatDuration} from "@/lib/format";

export function StoryboardPrintPage(props: Parameters<typeof StoryboardPrintPageContent>[0]) {
    return <StoryboardPrintPageContent key={JSON.stringify([props.projectId, props.episodeId])} {...props}/>;
}

function StoryboardPrintPageContent({
                                        projectId,
                                        episodeId,
                                    }: {
    projectId: string;
    episodeId: string;
}) {
    const projectResult = useLiveQuery(
        async () => ({projectId, project: (await db.projects.get(projectId)) ?? null}),
        [projectId],
    );
    const episodeResult = useLiveQuery(
        async () => ({projectId, episodeId, episode: (await db.episodes.get(episodeId)) ?? null}),
        [projectId, episodeId],
    );
    const shotsResult = useLiveQuery(async () => ({
        projectId, episodeId,
        shots: await db.shots.where("episodeId").equals(episodeId).sortBy("order"),
    }), [projectId, episodeId]);
    const assetsResult = useLiveQuery(async () => ({
        projectId,
        characters: await db.characters.where("projectId").equals(projectId).toArray(),
        scenes: await db.scenes.where("projectId").equals(projectId).toArray(),
    }), [projectId]);
    const project = projectResult?.projectId === projectId ? projectResult.project : undefined;
    const episode = episodeResult?.projectId === projectId && episodeResult.episodeId === episodeId
        ? episodeResult.episode : undefined;
    const loadedShots = shotsResult?.projectId === projectId && shotsResult.episodeId === episodeId
        ? shotsResult.shots : undefined;
    const loadedCharacters = assetsResult?.projectId === projectId ? assetsResult.characters : undefined;
    const loadedScenes = assetsResult?.projectId === projectId ? assetsResult.scenes : undefined;
    const shots = loadedShots;
    const characters = loadedCharacters;
    const scenes = loadedScenes;

    const relationAssets = useLiveQuery(async () => ({
        projectId,
        props: await db.props.where("projectId").equals(projectId).toArray(),
        styles: await db.styles.where("projectId").equals(projectId).toArray(),
    }), [projectId]);
    const props = relationAssets?.projectId === projectId ? relationAssets.props : undefined;
    const styles = relationAssets?.projectId === projectId ? relationAssets.styles : undefined;

    const media = useShotMedia(shots);

    if (
        media === undefined ||
        project === undefined ||
        episode === undefined ||
        shots === undefined ||
        characters === undefined ||
        props === undefined ||
        styles === undefined ||
        scenes === undefined
    ) {
        return <div className="p-8 text-sm">加载故事板…</div>;
    }
    if (project === null || episode === null || episode.projectId !== projectId || episode.id !== episodeId) {
        return <div className="p-8 text-sm">找不到当前故事板</div>;
    }

    const delivery = deriveEpisodeDelivery({
        project,
        episode,
        shots,
        characters,
        scenes,
        props,
        styles,
        media,
    });

    return (
        <main className="storyboard-print min-h-full bg-white px-4 py-6 sm:px-8 text-black">
            <div className="print-toolbar mx-auto mb-6 flex max-w-6xl flex-wrap items-center justify-between gap-3">
                <Button variant="outline" asChild>
                    <Link
                        to="/p/$projectId/e/$episodeId/produce"
                        params={{projectId, episodeId}}
                    >
                        <ArrowLeft/>
                        返回制作
                    </Link>
                </Button>
                <Button onClick={() => window.print()}>
                    <Printer/>
                    打印
                </Button>
            </div>

            <header className="storyboard-heading mx-auto max-w-6xl border-b border-black/20 pb-4">
                <p className="text-xs tracking-[0.18em] text-black/55">分镜故事板</p>
                <h1 className="mt-1 text-2xl font-semibold">{project.name}</h1>
                <div className="mt-2 flex gap-5 text-sm text-black/65">
                    {normalizeProjectMode(project.mode) === "series" ? <span>{episodeLabel(episode)}</span> : null}
                    <span>{delivery.rows.length} 镜</span>
                    <span>{formatDuration(delivery.totalDurationSec)}</span>
                </div>
            </header>

            {delivery.rows.length === 0 ? (
                <p className="mx-auto mt-12 max-w-6xl text-center text-sm text-black/50">
                    还没有镜头
                </p>
            ) : (
                <div
                    className="storyboard-grid mx-auto mt-6 grid max-w-6xl grid-cols-1 gap-4 md:grid-cols-2 print:grid-cols-2">
                    {delivery.rows.map((row) => (
                        <article
                            key={row.shot.id}
                            className="storyboard-card grid grid-cols-[minmax(0,1.2fr)_minmax(0,1fr)] rounded-lg border border-black/20"
                        >
                            <div className="aspect-video bg-neutral-100">
                                <MediaPreview
                                    mediaId={row.visualMediaId}
                                    empty="暂无首帧"
                                    className="size-full text-black/40"
                                />
                            </div>
                            <div className="flex min-w-0 flex-col p-3">
                                <div className="flex items-baseline justify-between gap-2">
                                    <strong className="text-sm">镜 {row.shotNumber || row.order}</strong>
                                    <span className="text-xs text-black/55">
                    {row.statusLabel} · {formatDuration(row.durationSec)}
                  </span>
                                </div>
                                <p className="mt-1 whitespace-pre-wrap break-words text-[11px] text-black/50">
                                    {row.beat}
                                    {row.scene ? ` · ${row.scene}` : ""}
                                </p>
                                <p className="mt-3 whitespace-pre-wrap break-words text-xs leading-5">
                                    {row.content || "未写内容"}
                                </p>
                                <dl className="mt-3 space-y-1 whitespace-pre-wrap break-words text-[11px] leading-4 text-black/65">
                                    <div>
                                        <dt className="inline font-medium">角色：</dt>
                                        <dd className="inline">{row.characters || "未选择"}</dd>
                                    </div>
                                    <div>
                                        <dt className="inline font-medium">道具：</dt>
                                        <dd className="inline">{row.props || "未选择"}</dd>
                                    </div>
                                    <div>
                                        <dt className="inline font-medium">风格：</dt>
                                        <dd className="inline">{row.style}（{row.styleSource}）</dd>
                                    </div>
                                    {row.notes ? <div>
                                        <dt className="inline font-medium">备注：</dt>
                                        <dd className="inline">{row.notes}</dd>
                                    </div> : null}
                                    {delivery.columns.map((column) => row.values[column.id] ? (
                                        <div key={column.id}>
                                            <dt className="inline font-medium">{column.label}：</dt>
                                            <dd className="inline">{row.values[column.id]}</dd>
                                        </div>
                                    ) : null)}
                                </dl>
                            </div>
                        </article>
                    ))}
                </div>
            )}
        </main>
    );
}

