    shot: Shot;
    striped: boolean;
    initiallyVisible: boolean;
    projectId: string;
    episodeId: string;
    selecting: boolean;
    selected: Set<string>;
    setSelected: Dispatch<SetStateAction<Set<string>>>;
    active?: boolean;
    onActivate: () => void;
    workspaceView: ShotWorkspaceView;
