export function MaterialDetailPanel({id, onClose, onSelect}: {
    id: string;
    onClose: () => void;
    onSelect: (id: string) => void
}) {
    // Parent selection changes are not router navigation. Keep the current
    // editor alive until its existing draft guard approves the switch.
    const [activeId, setActiveId] = useState(id);
    const result = useLiveQuery(async () => ({id: activeId, material: await db.libraryMaterials.get(activeId) ?? null}), [activeId]);
    const loadedMaterial = result?.id === activeId ? result.material : undefined;
    const lastMaterial = useRef<LibraryMaterial | undefined>(undefined);
    const [editing, setEditing] = useState(false);
    if (loadedMaterial) lastMaterial.current = loadedMaterial;
    const material = loadedMaterial ?? (editing && lastMaterial.current?.id === activeId ? lastMaterial.current : loadedMaterial);
    const select = (nextId: string) => {
        setActiveId(nextId);
        onSelect(nextId);
    };
    useEffect(() => {
        // No manual session exists while the current material is missing/loading.
        if (!material) setActiveId(id);
    }, [id, material]);
    return material ? <MaterialEditor key={material.id} material={material} requestedId={id} unavailable={!loadedMaterial} onEditingChange={setEditing} onClose={onClose} onSelect={select}/> :
        <Sheet open onOpenChange={(open) => {
            if (!open) onClose();
        }}><SheetContent
            className="material-detail"><SheetHeader><SheetTitle>素材详情</SheetTitle><SheetDescription>{material === null ? "素材不存在或已删除" : "正在读取素材…"}</SheetDescription></SheetHeader></SheetContent></Sheet>;
}

function MaterialEditor({material, requestedId, unavailable, onEditingChange, onClose, onSelect}: {
    material: LibraryMaterial;
    requestedId: string;
    unavailable: boolean;
    onEditingChange: (editing: boolean) => void;
    onClose: () => void;
    onSelect: (id: string) => void
}) {
    const [draft, setDraft] = useState<{ revision: number; name: string; notes: string; tags: string } | null>(null);
    const [pending, setPending] = useState(false);
    const pendingRef = useRef(false);
    const [error, setError] = useState("");
    const [notice, setNotice] = useState("");
    const [selectedRevision, setSelectedRevision] = useState<number | null>(null);
    const [projectId, setProjectId] = useState(material.scope.kind === "project" ? material.scope.id : "");
    const [targetScope, setTargetScope] = useState("global");
    const [promoting, setPromoting] = useState(false);
    const [deleting, setDeleting] = useState(false);
    const [releasing, setReleasing] = useState<string | null>(null);
    const fileInput = useRef<HTMLInputElement>(null);
    const guard = useMaterialDraftGuard(Boolean(draft), pending);
    useEffect(() => {onEditingChange(Boolean(draft) || pending);}, [draft, pending, onEditingChange]);
    const {requestClose} = guard;
    const latestRequestedId = useRef(requestedId);
    latestRequestedId.current = requestedId;
    const selectionRequest = useRef<string | undefined>(undefined);
    useEffect(() => {
        if (requestedId === material.id) {
            selectionRequest.current = undefined;
            return;
        }
        if (pending || selectionRequest.current === requestedId) return;
        selectionRequest.current = requestedId;
        requestClose(() => onSelect(latestRequestedId.current), () => {
            selectionRequest.current = undefined;
            onSelect(material.id);
        });
    }, [requestedId, material.id, pending, requestClose, onSelect]);
    const data = useLiveQuery(async () => ({
        versions: (await db.materialVersions.where("materialId").equals(material.id).toArray()).sort((a, b) => b.revision - a.revision),
        uses: await db.materialUses.where("materialId").equals(material.id).toArray(),
        events: (await db.materialEvents.where("materialId").equals(material.id).toArray()).sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
        projects: await db.projects.toArray(),
        ips: await db.ipProfiles.toArray(),
        links: await db.projectIpLinks.toArray(),
        derived: (await db.libraryMaterials.toArray()).filter((item) => item.source?.materialId === material.id),
    }), [material.id]);
    const version = data?.versions.find((item) => item.revision === (selectedRevision ?? material.revision));
    const values = draft ?? {
        revision: material.revision,
        name: material.name,
        notes: material.notes,
        tags: material.tags.join("，")
    };
    const materialScope = material.scope;
    const targetProjects = data?.projects.filter((project) => !project.archivedAt && (materialScope.kind === "global" || materialScope.kind === "project" && materialScope.id === project.id || materialScope.kind === "ip" && data.links.some((link) => link.projectId === project.id && link.ipId === materialScope.id)));

    function edit(patch: Partial<typeof values>) {
        setDraft({...values, ...patch});
        setError("");
    }

    async function action(work: () => Promise<unknown>, message: string) {
        if (pendingRef.current || unavailable) return;
        pendingRef.current = true;
        setPending(true);
        setError("");
        setNotice("");
        try {
            await work();
            setNotice(message);
        } catch (cause) {
            setError(cause instanceof Error ? cause.message : "操作失败，请重试");
        } finally {
            pendingRef.current = false;
            setPending(false);
        }
    }

    const operationsDisabled = unavailable || pending || Boolean(draft);
    const scopeLabel = materialScope.kind === "global" ? "全局素材" : materialScope.kind === "ip" ? `IP · ${data?.ips.find((ip) => ip.id === materialScope.id)?.name ?? "已不可用"}` : `项目 · ${data?.projects.find((project) => project.id === materialScope.id)?.name ?? "已删除"}`;
    const hasReferences = Boolean(data?.uses.length || data?.derived.length);
    return <><Sheet open onOpenChange={(open) => {
        if (!open) guard.requestClose(onClose);
    }}><SheetContent className="material-detail" showCloseButton={false}>
        {unavailable && <p role="alert">素材不存在或已删除，当前修改仍保留。请放弃修改或继续编辑。</p>}
        <SheetHeader className="material-detail-heading">
            <div><p className="material-eyebrow">{KIND_LABELS[material.kind]} · {scopeLabel}</p>
                <SheetTitle>{material.name}</SheetTitle><SheetDescription>版本 {material.revision}{material.archived ? " · 已归档" : " · 可复用"}</SheetDescription>
            </div>
            <Button size="icon" variant="ghost" aria-label="关闭素材详情" disabled={pending}
                    onClick={() => guard.requestClose(onClose)}><X/></Button></SheetHeader>
        <div className="material-detail-body">
            <MaterialPreview payload={version?.payload} inspect/>
            {data && data.versions.length > 1 &&
                <label className="material-field">查看历史版本<MaterialSelect label="查看历史版本"
                                                                              value={String(selectedRevision ?? material.revision)}
                                                                              onChange={(value) => setSelectedRevision(Number(value))}
                                                                              options={data.versions.map((item) => ({
                                                                                  value: String(item.revision),
                                                                                  label: `版本 ${item.revision} · ${new Date(item.createdAt).toLocaleDateString("zh-CN")}`
                                                                              }))}/></label>}
            {selectedRevision !== null && selectedRevision !== material.revision &&
                <p className="material-muted">当前预览历史版本；“用于项目”始终采用最新版本 {material.revision}。</p>}
            <section className="material-detail-section"><h3>素材信息</h3>
                <label className="material-field">名称<Input value={values.name} disabled={pending || material.archived}
                                                             onChange={(event) => edit({name: event.target.value})}/></label>
                <label className="material-field">备注<Textarea value={values.notes}
                                                                disabled={pending || material.archived} rows={3}
                                                                onChange={(event) => edit({notes: event.target.value})}
                                                                placeholder="用途、注意事项或创作背景"/></label>
                <label className="material-field">标签<Input value={values.tags} disabled={pending || material.archived}
                                                             onChange={(event) => edit({tags: event.target.value})}
                                                             placeholder="用逗号分隔"/></label>
                {draft && <div className="material-inline-actions"><Button disabled={unavailable || pending || !values.name.trim()}
                                                                           onClick={() => void action(async () => {
                                                                               await updateMaterialMetadata(material.id, {
                                                                                   name: values.name,
                                                                                   notes: values.notes,
                                                                                   tags: values.tags.split(/[,，]/).map((tag) => tag.trim()).filter(Boolean)
                                                                               }, values.revision);
                                                                               setDraft(null);
                                                                           }, "素材信息已保存，生成新的版本。")}>保存修改</Button><Button
                    variant="ghost" disabled={pending} onClick={() => setDraft(null)}>撤销修改</Button></div>}
            </section>
            <section className="material-detail-section"><h3>来源与版本</h3><p
                className="material-muted">{material.source ? `来自${material.source.materialId ? "另一份素材" : material.source.projectId === "studio" ? "工作室原件" : "项目原件"}，此处保存独立快照。` : "直接导入，原文件保存在素材版本中。"}</p>
                {version?.payload.type === "setting" && material.source?.entityId && material.source.projectId &&
                    <LegacySettingLink row={{
                        id: material.source.entityId,
                        ownerId: material.source.projectId,
                        kind: version.payload.kind
                    }}/>}
                {version?.payload.type === "setting" &&
                    <p className="material-muted">在原设定编辑页修改，返回后保存新快照；已有项目仍固定使用原版本。</p>}
                <div className="material-inline-actions"><Button variant="outline"
                                                                 disabled={operationsDisabled || material.archived}
                                                                 onClick={() => {
                                                                     if (version?.payload.type === "setting") void action(() => refreshSettingMaterial(material.id, material.revision), "已从原设定保存新版本。"); else fileInput.current?.click();
                                                                 }}><Upload
                    size={14}/>{version?.payload.type === "setting" ? "从原设定保存新版本" : "上传新版本"}
                </Button><Button variant="outline" disabled={operationsDisabled || material.archived}
                                 onClick={() => setPromoting(!promoting)}>复制到其他位置</Button></div>
                <input ref={fileInput} hidden type="file" accept={MATERIAL_ACCEPT} onChange={(event) => {
                    const file = event.target.files?.[0];
                    event.target.value = "";
                    if (file) void action(() => addFileMaterialVersion(material.id, file, material.revision), "新版本已保存，项目内容没有自动改变。");
                }}/>
                {promoting && <div className="material-action-block"><MaterialScopeSelect value={targetScope}
                                                                                          onChange={setTargetScope}
                                                                                          disabled={operationsDisabled}/><Button
                    disabled={operationsDisabled || scopeValue(material.scope) === targetScope}
                    onClick={() => {
                        let copyId: string | undefined;
                        void action(async () => {
                            const copy = await promoteMaterial(material.id, parseScope(targetScope));
                            copyId = copy.id;
                            setPromoting(false);
                        }, "独立副本已保存。").then(() => {
                            if (copyId) onSelect(copyId);
                        });
                    }}>保存独立副本</Button></div>}
            </section>
            <section className="material-detail-section"><h3>用于项目</h3><p
                className="material-muted">创建项目专属副本并固定版本，后续更新需手动确认。媒体会进入项目素材，不会自动替换镜头。</p>
                <div className="material-action-block"><MaterialSelect label="使用素材的目标项目" placeholder="选择项目"
                                                                       value={projectId}
                                                                       disabled={operationsDisabled || material.archived}
                                                                       onChange={setProjectId}
                                                                       options={(targetProjects ?? []).map((project) => ({
                                                                           value: project.id,
                                                                           label: project.name
                                                                       }))}/><Button
                    disabled={operationsDisabled || material.archived || !targetProjects?.some((project) => project.id === projectId)}
                    onClick={() => void action(() => useMaterialInProject(material.id, projectId), "已加入项目，版本固定。")}>用于项目</Button>
                </div>
                {data?.uses.length === 0 && <p className="material-muted">尚未用于项目。</p>}
                <ul className="material-use-list">{data?.uses.map((use) => <li key={use.id}>
                    <div><Link to="/p/$projectId"
                               params={{projectId: use.projectId}}>{data.projects.find((project) => project.id === use.projectId)?.name ?? "项目已删除"}<ArrowUpRight
                        size={12}/></Link><span>版本 {use.revision}{use.supersededBy ? " · 历史引用" : " · 当前采用"}</span>{use.targetKind !== "media" &&
                        <LegacySettingLink row={{kind: use.targetKind, id: use.targetId, ownerId: use.projectId}}/>}
                    </div>
                    <div className="material-inline-actions">{!use.supersededBy && use.revision < material.revision &&
                        <Button variant="outline" size="sm" disabled={operationsDisabled || material.archived}
                                onClick={() => void action(() => updateMaterialUse(use.id), "新版项目副本已加入，已有编辑内容和素材引用没有替换。")}>加入新版副本
                            v{material.revision}</Button>}<Button variant="ghost" size="sm"
                                                                  disabled={operationsDisabled} onClick={() => {
                        setError("");
                        setReleasing(use.id);
                    }}>{use.targetKind === "media" ? "移除未使用副本" : "解除引用"}</Button></div>
                </li>)}</ul>
            </section>
            <section className="material-detail-section"><h3><History size={14} aria-hidden/>操作记录</h3>
                <ul className="material-event-list">{data?.events.slice(0, 30).map((event) => <li key={event.id}>
                    <span>{({
                        create: "导入素材",
                        promote: "建立独立快照",
                        version: "保存新版本",
                        archive: "归档素材",
                        restore: "恢复素材",
                        use: "加入项目",
                        "update-use": "加入新版项目副本",
                        release: "移除未使用副本"
                    } as Record<string, string>)[event.action] ?? "素材变更"}{event.detail ? ` · ${event.detail}` : ""}</span>
                    <time>{new Date(event.createdAt).toLocaleString("zh-CN")}</time>
                </li>)}</ul>
            </section>
            {error && <p role="alert" className="material-error">{error}</p>}{notice &&
            <p role="status" className="material-notice">{notice}</p>}{pending && <p role="status">正在保存…</p>}
            <div className="material-inline-actions material-danger-zone"><Button variant="outline"
                                                                                  disabled={operationsDisabled}
                                                                                  onClick={() => void action(() => setMaterialArchived(material.id, !material.archived), material.archived ? "已恢复素材。" : "已归档，已有项目引用继续保留。")}><Archive
                size={14}/>{material.archived ? "恢复素材" : "归档"}</Button><Button variant="ghost"
                                                                                     disabled={operationsDisabled || !data || hasReferences || !material.archived}
                                                                                     onClick={() => setDeleting(true)}><Trash2
                size={14}/>永久删除</Button></div>
            {!material.archived && !hasReferences && <p className="material-muted">需要永久删除时，请先归档素材。</p>}
            {hasReferences &&
                <p className="material-muted">当前有 {data?.uses.length} 条项目引用、{data?.derived.length} 份衍生素材，不能永久删除；可归档。</p>}
        </div>
    </SheetContent></Sheet>{guard.dialog}<AlertDialog open={deleting} onOpenChange={(open) => {
        if (!pending) setDeleting(open);
    }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>永久删除“{material.name}”？</AlertDialogTitle><AlertDialogDescription>删除所有版本和文件，操作不可撤销。保存前会再次检查引用。</AlertDialogDescription></AlertDialogHeader>{error &&
        <p role="alert" className="material-error">{error}</p>}<AlertDialogFooter><Button variant="outline"
                                                                                          disabled={pending}
                                                                                          onClick={() => setDeleting(false)}>取消</Button><Button
        variant="destructive" disabled={pending} onClick={() => void action(async () => {
        await deleteMaterial(material.id);
        setDeleting(false);
        onClose();
    }, "")}>永久删除</Button></AlertDialogFooter></AlertDialogContent></AlertDialog>
        <AlertDialog open={Boolean(releasing)} onOpenChange={(open) => {
            if (!pending && !open) setReleasing(null);
        }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>移除这条项目引用？</AlertDialogTitle><AlertDialogDescription>删除该项目未被镜头、封面或任务历史使用的文件及使用记录，保留素材库原件。创作设定请先在项目编辑页删除，再解除引用。</AlertDialogDescription></AlertDialogHeader>{error &&
            <p role="alert" className="material-error">{error}</p>}<AlertDialogFooter><Button variant="outline"
                                                                                              disabled={pending}
                                                                                              onClick={() => setReleasing(null)}>取消</Button><Button
            variant="destructive" disabled={pending || !releasing} onClick={() => void action(async () => {
            await releaseMaterialUse(releasing!);
            setReleasing(null);
        }, "项目引用已移除，素材库版本继续保留。")}>确认移除</Button></AlertDialogFooter></AlertDialogContent></AlertDialog></>;
}

import {useManualDraftGuard} from "@/lib/useManualDraftGuard";
import {type ReactNode, useEffect, useRef, useState} from "react";
import {useLiveQuery} from "dexie-react-hooks";
import {toast} from "sonner";
import {db} from "@/db/database";
import {patchProjectDetails} from "@/db/repo";
import {ASPECT_PRESET_IDS, type AspectPresetId, getProjectKind, type Project} from "@/domain/types";
import {
    APIMART_IMAGE_MODELS,
    type ApimartImageModel,
    apimartImageSizes,
    defaultImageGeneration,
    defaultVideoGeneration,
    IMAGE_EXT_VERSIONS,
    IMAGE_QUALITIES,
    IMAGE_RESOLUTIONS,
    isApimartImage25,
    isApimartImageExt,
    isApimartImageModel,
    OUTPUT_PROFILE_VERSION,
    type ProjectGenerationDefaults,
    validateGenerationDefaults,
    VIDEO_RATIOS,
    VIDEO_RESOLUTIONS,
} from "@/domain/output";
import {acknowledgeOutputDraft, outputDraftPatch, projectOutputValue, rebaseOutputDraft, type ProjectOutputDraft} from "@/lib/projectOutputDraft";
import {AssetTextField} from "@/components/assets/AssetTextField";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {Select, SelectContent, SelectItem, SelectTrigger, SelectValue} from "@/components/ui/select";

function SettingSelect({label, value, options, onChange, disabled}: {
    label: string; value: string; options: readonly (string | { value: string; label: string })[];
    onChange: (value: string) => void; disabled?: boolean;
}) {
    const choices = options.map((option) => typeof option === "string" ? {value: option, label: option} : option);
    const known = choices.some((option) => option.value === value);
    return (
        <div className="grid min-w-0 gap-2">
            <span className="text-xs font-medium">{label}</span>
            <Select value={value || "__invalid"} onValueChange={onChange} disabled={disabled}>
                <SelectTrigger aria-label={label} className="w-full"><SelectValue/></SelectTrigger>
                <SelectContent>
                    {!known && <SelectItem value={value || "__invalid"}>待调整：{value || "未填写"}</SelectItem>}
                    {choices.map((option) => <SelectItem key={option.value}
                                                         value={option.value}>{option.label}</SelectItem>)}
                </SelectContent>
            </Select>
        </div>
    );
}

function Section({title, description, children}: { title: string; description: string; children: ReactNode }) {
    return <section className="min-w-0 space-y-4 border-t pt-5">
        <div><h3 className="text-sm font-semibold">{title}</h3><p
            className="text-muted-foreground mt-1 text-xs leading-5">{description}</p></div>
        {children}
    </section>;
}

export function ProjectSettingsPanel({project, onOutputState, unavailable = false}: {
    project: Project;
    unavailable?: boolean;
    onOutputState: (state: { dirty: boolean; saving: boolean }) => void
}) {
    const styles = useLiveQuery(() => db.styles.where("projectId").equals(project.id).sortBy("name"), [project.id]);
    const [stylePending, setStylePending] = useState(false);

    async function setStyle(value: string) {
        setStylePending(true);
        try {
            await patchProjectDetails(project.id, {defaultStyleId: value === "none" ? undefined : value}, {defaultStyleId: project.defaultStyleId});
        } catch (error) {
            toast.error(error instanceof Error ? error.message : "风格保存失败");
        } finally {
            setStylePending(false);
        }
    }

    return <div className="min-w-0 space-y-6">
        <div className="space-y-4">
            <AssetTextField key={`${project.id}:name`} draftKey={`${project.id}:name`} projectId={project.id}
                            label="项目名称" value={project.name}
                            persist={(name, baseline) => patchProjectDetails(project.id, {name}, {name: baseline})}/>
            <AssetTextField key={`${project.id}:brief`} draftKey={`${project.id}:brief`} projectId={project.id}
                            label="创作简述" value={project.brief ?? ""} multiline
                            placeholder="想表达什么，希望作品带来什么感受"
                            persist={(brief, baseline) => patchProjectDetails(project.id, {brief}, {brief: baseline})}/>
            <details className="rounded-xl border p-4">
                <summary className="cursor-pointer text-sm font-medium">补充创作信息 <span
                    className="text-muted-foreground text-xs font-normal">· 可选</span></summary>
                <div className="mt-4 grid gap-4 sm:grid-cols-2">
                    {([
                        ["genre", "类型 / 题材", "如：悬疑、都市、成长"],
                        ["audience", "目标观众", "希望作品面向哪些人"],
                        ["tone", "叙事基调", "如：克制、温暖、荒诞"],
                    ] as const).map(([field, label, placeholder]) => <AssetTextField key={`${project.id}:${field}`}
                                                                                     draftKey={`${project.id}:${field}`}
                                                                                     projectId={project.id}
                                                                                     label={label}
                                                                                     placeholder={placeholder}
                                                                                     value={project[field] ?? ""}
                                                                                     persist={(value, baseline) => patchProjectDetails(project.id, {[field]: value}, {[field]: baseline})}/>)}
                </div>
            </details>
        </div>
        {getProjectKind(project) === "video" && <>
            <Section title="默认视觉风格"
                     description="镜头默认跟随这里的风格；镜头中单独选择的风格会保留。可先在世界 → 风格中建立本项目的风格。">
                <SettingSelect label="项目风格" value={project.defaultStyleId ?? "none"}
                               disabled={unavailable || styles === undefined || stylePending}
                               options={[{
                                   value: "none",
                                   label: "暂不设置"
                               }, ...(styles ?? []).map((style) => ({
                                   value: style.id,
                                   label: style.name || "未命名风格"
                               }))]}
                               onChange={(value) => void setStyle(value)}/>
                {stylePending && <p role="status" className="text-muted-foreground text-xs">正在保存风格…</p>}
            </Section>
            <ProjectOutputSettings key={project.id} project={project} unavailable={unavailable} onOutputState={onOutputState}/>
        </>}
    </div>;
}

const IMAGE_MODEL_LABELS: Record<ApimartImageModel, string> = {
    "gpt-image-2": "APIMart · GPT Image 2（标准通道）",
    "gpt-image-2.5-flare": "APIMart · GPT Image 2.5 Flare",
    "gpt-image-2.5-sunburst": "APIMart · GPT Image 2.5 Sunburst",
    "gpt-image-2.5-ext": "APIMart · GPT Image 2.5 Ext",
};

function ProjectOutputSettings({project, onOutputState, unavailable = false}: {
    project: Project;
    unavailable?: boolean;
    onOutputState: (state: { dirty: boolean; saving: boolean }) => void
}) {
    const [output, setOutput] = useState<ProjectOutputDraft>(() => {
        const value = projectOutputValue(project);
        return {value, baseline: structuredClone(value), observed: value};
    });
    const {aspectPreset: ratio, generationDefaults: draft} = output.value;
    const setRatio = (aspectPreset: AspectPresetId) => setOutput(current => ({...current, value: {...current.value, aspectPreset}}));
    const setDraft = (generationDefaults: ProjectGenerationDefaults) => setOutput(current => ({...current, value: {...current.value, generationDefaults}}));
    const [saving, setSaving] = useState(false);
    const saveBusy = useRef(false);
    const latestProject = useRef(project);
    latestProject.current = project;
    const patch = outputDraftPatch(output);
    const ratioDirty = "aspectPreset" in patch;
    const defaultsDirty = "generationDefaults" in patch;
    const liveRatio = project.aspectPreset;
    const liveDefaults = project.generationDefaults;
    useEffect(() => {
        if (saving) return;
        setOutput(current => rebaseOutputDraft(current, projectOutputValue({aspectPreset: liveRatio, generationDefaults: liveDefaults})));
    }, [liveRatio, liveDefaults, saving, ratioDirty, defaultsDirty]);
    const [saveError, setSaveError] = useState<string>();
    const errors = validateGenerationDefaults(draft);
    const dirty = ratioDirty || defaultsDirty;
    useEffect(() => {
        onOutputState({dirty, saving});
    }, [dirty, saving, onOutputState]);
    const navigationGuard = useManualDraftGuard(dirty, saving, () => {
        const value = projectOutputValue(project);
        setOutput({value, baseline: structuredClone(value), observed: value});
        setSaveError(undefined);
    });
    const image = draft.image;
    const video = draft.video;
    const imageKnown = Boolean(image && image.provider === "apimart" && isApimartImageModel(image.model) && image.profileVersion === OUTPUT_PROFILE_VERSION);
    const videoKnown = video?.provider === "apimart" && video.model === "MiniMax-H3" && video.profileVersion === OUTPUT_PROFILE_VERSION;
    const imageModel = imageKnown ? image!.model : undefined;
    const updateImage = (patch: Partial<NonNullable<ProjectGenerationDefaults["image"]>>) => {
        if (image) setDraft({...draft, image: {...image, ...patch}});
    };
    const updateVideo = (patch: Partial<NonNullable<ProjectGenerationDefaults["video"]>>) => {
        if (video) setDraft({...draft, video: {...video, ...patch}});
    };

    async function save() {
        if (unavailable || errors.length || saveBusy.current) return;
        saveBusy.current = true;
        setSaving(true);
        setSaveError(undefined);
        try {
            const patch = outputDraftPatch(output);
            await patchProjectDetails(project.id, patch, output.baseline);
            const currentProject = await db.projects.get(project.id);
            if (!currentProject) throw new Error("项目不存在，无法确认输出配置");
            const latest = projectOutputValue(latestProject.current);
            const authoritative = projectOutputValue(currentProject);
            setOutput(current => acknowledgeOutputDraft(current, patch, latest, authoritative));
            toast.success("输出配置已保存");
        } catch (error) {
            setSaveError(error instanceof Error ? error.message : "输出配置保存失败，请重试");
        } finally {
            saveBusy.current = false;
            setSaving(false);
        }
    }

    return <>{navigationGuard}<Section title="画幅与生成默认值"
                    description="画幅表达作品的目标。图片和视频可分别选择模型参数，也可以保持手动制作；保存配置不会发起生成。">
        <fieldset disabled={saving || unavailable} className="min-w-0 space-y-5">
            <SettingSelect label="项目目标画幅" value={ratio} options={ASPECT_PRESET_IDS}
                           onChange={(value) => setRatio(value as AspectPresetId)}/>
            <div className="rounded-xl border p-4 space-y-4">
                <h4 className="text-sm font-medium">图片默认值</h4>
                <SettingSelect label="图片模型" value={!image ? "manual" : imageKnown ? image.model : "unsupported"}
                               options={[{
                                   value: "manual",
                                   label: "不设置生成默认值"
                               }, ...APIMART_IMAGE_MODELS.map((model) => ({
                                   value: model,
                                   label: IMAGE_MODEL_LABELS[model]
                               })), ...(!imageKnown && image ? [{
                                   value: "unsupported",
                                   label: `待确认：${image.model} / ${image.profileVersion}`
                               }] : [])]}
                               onChange={(value) => value !== "unsupported" && setDraft({
                                   ...draft,
                                   image: value === "manual" ? undefined : defaultImageGeneration(ratio, value as ApimartImageModel)
                               })}/>
                {image && <>
                    <div className="grid gap-4 sm:grid-cols-2">
                        <SettingSelect label="图片比例" value={image.size}
                                       options={[...apimartImageSizes(image.model), {
                                           value: "auto",
                                           label: "自动（默认 1:1）"
                                       }]} onChange={(size) => updateImage({size})}/>
                        <SettingSelect label="图片清晰度" value={image.resolution} options={IMAGE_RESOLUTIONS}
                                       onChange={(resolution) => updateImage({resolution})}/>
                        {imageModel && isApimartImage25(imageModel) &&
                            <SettingSelect label="画质" value={image.quality ?? "auto"} options={[...IMAGE_QUALITIES]}
                                           onChange={(quality) => updateImage({quality})}/>}
                        {imageModel && isApimartImageExt(imageModel) &&
                            <SettingSelect label="版本" value={image.version ?? "flare"}
                                           options={[...IMAGE_EXT_VERSIONS]}
                                           onChange={(version) => updateImage({version})}/>}
                    </div>
                    <p className="text-muted-foreground text-xs leading-5">清晰度是模型的输出档位，实际像素随比例而变化。一次生成
                        1
                        张图片。{imageModel && isApimartImage25(imageModel) ? " auto 会按最高档预扣，完成后再按实际用量结算。" : ""}</p>
                </>}
            </div>
            <div className="rounded-xl border p-4 space-y-4">
                <h4 className="text-sm font-medium">视频默认值</h4>
                <SettingSelect label="视频模型" value={!video ? "manual" : videoKnown ? "MiniMax-H3" : "unsupported"}
                               options={[{value: "manual", label: "不设置生成默认值"}, {
                                   value: "MiniMax-H3",
                                   label: "APIMart · MiniMax H3"
                               }, ...(!videoKnown && video ? [{
                                   value: "unsupported",
                                   label: `待确认：${video.model} / ${video.profileVersion}`
                               }] : [])]}
                               onChange={(value) => value !== "unsupported" && setDraft({
                                   ...draft,
                                   video: value === "manual" ? undefined : defaultVideoGeneration(ratio)
                               })}/>
                {video && <>
                    <SettingSelect label="视频生成方式" value={video.mode}
                                   options={[{value: "text", label: "文字生视频"}, {
                                       value: "frames",
                                       label: "首帧 / 尾帧生视频"
                                   }, {value: "reference", label: "参考素材生视频"}]}
                                   onChange={(mode) => updateVideo({mode})}/>
                    <div className="grid gap-4 sm:grid-cols-2">
                        <SettingSelect label="视频比例" value={video.aspectRatio} options={video.mode === "frames" ? [{
                            value: "adaptive",
                            label: "跟随输入图片"
                        }] : video.mode === "reference" ? [...VIDEO_RATIOS, {
                            value: "adaptive",
                            label: "跟随参考素材"
                        }] : VIDEO_RATIOS} onChange={(aspectRatio) => updateVideo({aspectRatio})}/>
                        <SettingSelect label="视频分辨率" value={video.resolution} options={VIDEO_RESOLUTIONS}
                                       onChange={(resolution) => updateVideo({resolution})}/>
                        <label className="grid gap-2 text-xs font-medium">默认生成时长（秒）
                            <Input type="number" min={4} max={15} step={1}
                                   value={Number.isFinite(video.duration) ? video.duration : ""}
                                   onChange={(event) => updateVideo({duration: event.target.value === "" ? 0 : Number(event.target.value)})}/>
                        </label>
                    </div>
                    <p className="text-muted-foreground text-xs leading-5">支持 4–15
                        秒整数。已有镜头的分镜时长保持原值。{video.mode === "frames" ? "首尾帧决定视频比例，项目画幅不会覆盖输入图片。" : "生成时仍需检查素材尺寸和角色，避免首尾帧与参考素材混用。"}</p>
                </>}
            </div>
        </fieldset>
        {errors.length > 0 &&
            <ul role="alert" className="text-destructive list-inside list-disc text-xs leading-5">{errors.map((error) =>
                <li key={error}>{error}</li>)}</ul>}
        {saveError && <p role="alert" className="text-destructive text-xs">{saveError}</p>}
        <div className="flex flex-wrap items-center justify-between gap-3">
            <p role="status"
               className="text-muted-foreground text-xs">{saving ? "正在保存…" : dirty ? "输出配置尚未保存" : "输出配置已保存"}</p>
            <div className="flex gap-2">
                <Button variant="ghost" size="sm" disabled={!dirty || saving} onClick={() => {
                    const value = projectOutputValue(project);
                    setOutput({value, baseline: structuredClone(value), observed: value});
                    setSaveError(undefined);
                }}>{saveError ? "采用最新内容" : "撤销修改"}</Button>
                <Button size="sm" disabled={unavailable || !dirty || saving || errors.length > 0}
                        onClick={() => void save()}>保存输出配置</Button>
            </div>
        </div>
    </Section></>;
}

import {WorkspaceUnavailableContext} from "@/lib/workspaceAvailability";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle
} from "@/components/ui/alert-dialog";
import {ProjectSettingsPanel} from "./ProjectSettingsPanel";
import {flushPendingDrafts} from "@/lib/debouncedDraft";
import {Link, Navigate, Outlet, useNavigate, useRouterState} from "@tanstack/react-router";
import {useLiveQuery} from "dexie-react-hooks";
import {ChevronLeft, Download, Library, Settings2} from "lucide-react";
import {useRef, useState} from "react";
import {toast} from "sonner";
import {Still} from "@/components/studio/Still";
import {Button} from "@/components/ui/button";
import {Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle,} from "@/components/ui/dialog";
import {db} from "@/db/database";
import {patchProjectOutput} from "@/db/repo";
import {episodeLabel, normalizeProjectMode,} from "@/domain/types";
import {IMAGE_ACCEPT, pickMediaFile, uploadMediaFile} from "@/lib/media";
import {downloadBlob, exportProjectZip} from "@/lib/projectPackage";
import {cn} from "@/lib/utils";
import {shouldRedirectAudioMusicChild} from "@/lib/audio/workspaceRoute";

const SERIES_STEPS = [
    {id: "episodes", label: "集", to: "/p/$projectId" as const, exact: true},
    {id: "world", label: "世界", to: "/p/$projectId/world" as const, exact: false},
];

const EPISODE_STEPS = [
    {id: "story", label: "故事", to: "/p/$projectId/e/$episodeId" as const, exact: true},
    {id: "shots", label: "分镜", to: "/p/$projectId/e/$episodeId/shots" as const, exact: false},
    {id: "produce", label: "制作", to: "/p/$projectId/e/$episodeId/produce" as const, exact: false},
];

function episodeIdFromPath(pathname: string, projectId: string): string | undefined {
    const prefix = `/p/${projectId}/e/`;
    if (!pathname.startsWith(prefix)) return undefined;
    return pathname.slice(prefix.length).split("/")[0] || undefined;
}

export function WorkspaceChrome({projectId}: { projectId: string }) {
    const navigate = useNavigate();
    const pathname = useRouterState({select: (state) => state.location.pathname});
    const episodeId = episodeIdFromPath(pathname, projectId);
    const projectResult = useLiveQuery(
        async () => ({projectId, project: (await db.projects.get(projectId)) ?? null}),
        [projectId],
    );
    const currentEpisodeResult = useLiveQuery(
        async () => {
            if (!episodeId) return {projectId, episodeId, episode: null};
            const row = await db.episodes.get(episodeId);
            return {projectId, episodeId, episode: row?.projectId === projectId ? row : null};
        },
        [episodeId, projectId],
    );
    const firstEpisodeResult = useLiveQuery(async () => {
        const rows = await db.episodes.where("projectId").equals(projectId).sortBy("order");
        return {projectId, episode: rows[0] ?? null};
    }, [projectId]);
    const loadedProject = projectResult?.projectId === projectId ? projectResult.project : undefined;
    const lastProject = useRef(loadedProject);
    if (loadedProject) lastProject.current = loadedProject;
    // Snapshot is layout/session data only. Missing rows are shown explicitly;
    // controls and descendant writes are disabled while preserving the Outlet.
    const project = loadedProject ?? (lastProject.current?.id === projectId ? lastProject.current : loadedProject);
    const currentEpisode = currentEpisodeResult?.projectId === projectId && currentEpisodeResult.episodeId === episodeId
        ? currentEpisodeResult.episode : undefined;
    const firstProjectEpisode = firstEpisodeResult?.projectId === projectId ? firstEpisodeResult.episode : undefined;
    const lastEpisode = useRef(currentEpisode);
    if (currentEpisode) lastEpisode.current = currentEpisode;
    const previouslyLoadedEpisode = lastEpisode.current?.id === episodeId;
    const [backingUp, setBackingUp] = useState(false);
    const [settingsOpen, setSettingsOpen] = useState(false);
    const [outputState, setOutputState] = useState({dirty: false, saving: false});
    const [confirmSettingsClose, setConfirmSettingsClose] = useState(false);

    function changeSettingsOpen(open: boolean) {
        if (!open && outputState.saving) return;
        if (!open && outputState.dirty) {
            setConfirmSettingsClose(true);
            return;
        }
        setOutputState({dirty: false, saving: false});
        setSettingsOpen(open);
    }

    if (
        project === undefined ||
        (project && normalizeProjectMode(project.mode) === "film" && firstProjectEpisode === undefined)
    ) {
        return <div className="text-muted-foreground p-10 text-sm">加载项目…</div>;
    }

    if (project === null) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center gap-3">
                <p>找不到这个项目</p>
                <Button onClick={() => void navigate({to: "/projects"})}>返回工作室</Button>
            </div>
        );
    }

    const projectMissing = loadedProject === null;
    const episodeMissing = Boolean(episodeId && currentEpisode === null);
    const unavailable = projectMissing || episodeMissing;
    const outputProtected = outputState.dirty || outputState.saving;
    const kind = project.kind ?? "video";
    if (!["video", "audio", "music"].includes(kind)) return <div role="alert" className="p-8">不支持的项目类型</div>;
    const mode = normalizeProjectMode(project.mode);
    const projectHome = pathname === `/p/${projectId}` || pathname === `/p/${projectId}/`;

    if (!unavailable && shouldRedirectAudioMusicChild(kind, projectId, pathname)) return <Navigate to="/p/$projectId"
                                                                                   params={{projectId}} replace/>;

    if (episodeId && currentEpisode === null && !previouslyLoadedEpisode && !outputProtected && !projectMissing) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center gap-3">
                <p>找不到这一集</p>
                <Button onClick={() => void navigate({to: "/p/$projectId", params: {projectId}})}>
                    返回项目
                </Button>
            </div>
        );
    }

    if (!unavailable && !outputProtected && kind === "video" && mode === "film" && firstProjectEpisode === null && !previouslyLoadedEpisode && !projectHome && pathname !== `/p/${projectId}/memory`) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center gap-3">
                <p>这个单片项目缺少内部集</p>
                <Button onClick={() => void navigate({to: "/p/$projectId", params: {projectId}})}>
                    修复项目
                </Button>
            </div>
        );
    }

    // A same-project episode read must not unmount settings or the Outlet.
    // Its previous episode is hidden until the requested identity resolves.
    const episode = currentEpisode || undefined;
    const filmEpisode = kind === "video" && mode === "film" ? firstProjectEpisode || undefined : undefined;
    const title = mode === "film" ? project.name : episode ? episodeLabel(episode) : project.name;
    const backToStudio = mode === "film" || !episode;

    async function uploadCover() {
        try {
            const file = await pickMediaFile(IMAGE_ACCEPT);
            if (!file) return;
            const uploaded = await uploadMediaFile(projectId, file);
            await patchProjectOutput(projectId, {coverMediaId: uploaded.id});
        } catch (err) {
            toast.error(err instanceof Error ? err.message : "上传封面失败");
        }
    }

    async function clearCover() {
        try {
            await patchProjectOutput(projectId, {coverMediaId: null});
        } catch (err) {
            toast.error(err instanceof Error ? err.message : "清除封面失败");
        }
    }

    return (
        <WorkspaceUnavailableContext value={unavailable}>
        <div
            className={cn("workspace-shell bg-background flex flex-col", kind !== "video" ? "h-dvh overflow-hidden" : "h-screen")}>
            {unavailable && <div className="p-4">
                <p role="alert">{projectMissing ? "找不到这个项目" : "找不到这一集"}。已打开的修改仍保留，可复制或关闭；当前内容不能保存。</p>
                <Button className="mt-3" variant="outline" onClick={() => void navigate({to: "/projects"})}>返回工作室</Button>
            </div>}
            <header hidden={unavailable} style={unavailable ? {display: "none"} : undefined}
                className="workspace-header grid min-h-14 shrink-0 grid-cols-[minmax(0,1fr)_auto] items-center gap-x-2 gap-y-2 border-b px-3 py-2 sm:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] sm:px-4">
                <div className="col-start-1 row-start-1 flex min-w-0 items-center gap-1">
                    {backToStudio ? (
                        <Button variant="ghost" size="icon-sm" asChild>
                            <Link to="/projects" aria-label="返回工作室">
                                <ChevronLeft/>
                            </Link>
                        </Button>
                    ) : (
                        <Button variant="ghost" size="icon-sm" asChild>
                            <Link to="/p/$projectId" params={{projectId}} aria-label="返回集列表">
                                <ChevronLeft/>
                            </Link>
                        </Button>
                    )}
                    <span className="truncate text-[15px] font-medium">{title}</span>
                </div>
                <nav
                    className="text-muted-foreground col-span-2 row-start-2 flex items-center justify-center gap-6 text-[13px] sm:col-span-1 sm:col-start-2 sm:row-start-1">
                    {kind !== "video" ? <Link to="/p/$projectId" params={{projectId}}
                                              className={cn("hover:text-foreground", projectHome && "text-foreground font-medium")}>{kind === "audio" ? "音频制作" : "音乐创作"}</Link> : filmEpisode ? (
                        <>
                            <Link
                                to="/p/$projectId/e/$episodeId"
                                params={{projectId, episodeId: filmEpisode.id}}
                                activeOptions={{exact: true}}
                                className={cn(
                                    "hover:text-foreground",
                                    (pathname === `/p/${projectId}/e/${filmEpisode.id}` ||
                                        pathname === `/p/${projectId}/e/${filmEpisode.id}/`) &&
                                    "text-foreground font-medium",
                                )}
                            >
                                故事
                            </Link>
                            <Link
                                to="/p/$projectId/world"
                                params={{projectId}}
                                className={cn(
                                    "hover:text-foreground",
                                    (pathname.startsWith(`/p/${projectId}/world`) ||
                                        pathname.startsWith(`/p/${projectId}/assets`)) &&
                                    "text-foreground font-medium",
                                )}
                            >
                                世界
                            </Link>
                            <Link
                                to="/p/$projectId/e/$episodeId/shots"
                                params={{projectId, episodeId: filmEpisode.id}}
                                search={{shot: undefined}}
                                className={cn(
                                    "hover:text-foreground",
                                    pathname.startsWith(`/p/${projectId}/e/${filmEpisode.id}/shots`) &&
                                    "text-foreground font-medium",
                                )}
                            >
                                分镜
                            </Link>
                            <Link
                                to="/p/$projectId/e/$episodeId/produce"
                                params={{projectId, episodeId: filmEpisode.id}}
                                className={cn(
                                    "hover:text-foreground",
                                    pathname.startsWith(`/p/${projectId}/e/${filmEpisode.id}/produce`) &&
                                    "text-foreground font-medium",
                                )}
                            >
                                制作
                            </Link>
                        </>
                    ) : mode === "film" ? null : episode ? (
                        <>
                            {EPISODE_STEPS.map((step) => {
                                const href = step.to
                                    .replace("$projectId", projectId)
                                    .replace("$episodeId", episode.id);
                                const active = step.exact
                                    ? pathname === href || pathname === `${href}/`
                                    : pathname.startsWith(href);
                                return (
                                    <Link
                                        key={step.id}
                                        to={step.to}
                                        params={{projectId, episodeId: episode.id}}
                                        search={step.id === "shots" ? {shot: undefined} : undefined}
                                        activeOptions={{exact: step.exact}}
                                        className={cn("hover:text-foreground", active && "text-foreground font-medium")}
                                    >
                                        {step.label}
                                    </Link>
                                );
                            })}
                        </>
                    ) : (
                        <>
                            {SERIES_STEPS.map((step) => {
                                const href = step.to.replace("$projectId", projectId);
                                const active = step.exact
                                    ? pathname === href || pathname === `${href}/`
                                    : pathname.startsWith(`/p/${projectId}/world`) ||
                                    pathname.startsWith(`/p/${projectId}/assets`);
                                return (
                                    <Link
                                        key={step.id}
                                        to={step.to}
                                        params={{projectId}}
                                        activeOptions={{exact: step.exact}}
                                        className={cn("hover:text-foreground", active && "text-foreground font-medium")}
                                    >
                                        {step.label}
                                    </Link>
                                );
                            })}
                        </>
                    )}
                    <Link to="/p/$projectId/memory" params={{projectId}}
                          className={cn("hover:text-foreground", pathname === `/p/${projectId}/memory` && "text-foreground font-medium")}>记忆</Link>
                </nav>
                <div className="col-start-2 row-start-1 flex items-center justify-end gap-1 sm:col-start-3">
                    <Button variant="ghost" size="sm" asChild><Link to="/assets" search={{project: projectId}}
                                                                    aria-label="项目素材"><Library/><span
                        className="hidden sm:inline">素材</span></Link></Button>
                    <Button variant="ghost" size="sm" onClick={() => changeSettingsOpen(true)} aria-label="项目设定">
                        <Settings2/><span className="hidden sm:inline">项目设定</span>
                    </Button>
                    <Button
                        variant="outline"
                        size="sm"
                        disabled={backingUp}
                        onClick={() => {
                            setBackingUp(true);
                            void flushPendingDrafts(projectId)
                                .then(() => exportProjectZip(projectId))
                                .then((blob) => {
                                    downloadBlob(blob, `${project.name}.zip`);
                                    toast.success("项目备份已下载");
                                })
                                .catch((error: unknown) => toast.error(
                                    error instanceof Error ? `备份失败：${error.message}` : "备份失败，请重试",
                                ))
                                .finally(() => setBackingUp(false));
                        }}
                    >
                        <Download/>
                        {backingUp ? "正在保存并备份…" : "备份项目"}
                    </Button>
                </div>
            </header>
            <div className="min-h-0 flex-1" inert={unavailable}>
                <Outlet/>
            </div>

            <Dialog open={settingsOpen && (!unavailable || outputProtected)} onOpenChange={changeSettingsOpen}>
                <DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-2xl">
                    <DialogHeader>
                        <DialogTitle>项目设定</DialogTitle>
                    </DialogHeader>
                    <ProjectSettingsPanel project={project} unavailable={unavailable} onOutputState={setOutputState}/>
                    <div>
                        <p className="text-sm font-medium">项目封面</p>
                        <div className="mt-2 flex items-start gap-4">
                            <div
                                className="aspect-[2/3] w-28 overflow-hidden rounded-xl bg-card ring-foreground/8 ring-1">
                                <Still mediaId={project.coverMediaId} title={project.name}/>
                            </div>
                            <div className="flex flex-col gap-2">
                                <Button variant="outline" size="sm" disabled={unavailable} onClick={() => void uploadCover()}>
                                    {project.coverMediaId ? "更换封面" : "上传封面"}
                                </Button>
                                {project.coverMediaId ? (
                                    <Button variant="ghost" size="sm" disabled={unavailable} onClick={() => void clearCover()}>
                                        清除封面
                                    </Button>
                                ) : (
                                    <p className="text-muted-foreground text-xs leading-5">
                                        {kind === "video" ? "未设置时，项目库会用最早镜头的首帧作封面。" : "为项目上传一张封面，方便在项目库中识别。"}
                                    </p>
                                )}
                            </div>
                        </div>
                    </div>
                    <DialogFooter>
                        <Button variant="outline" disabled={outputState.saving}
                                onClick={() => changeSettingsOpen(false)}>
                            完成
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
            <AlertDialog open={confirmSettingsClose} onOpenChange={setConfirmSettingsClose}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>输出配置尚未保存</AlertDialogTitle>
                        <AlertDialogDescription>返回后可保存当前画幅和生成默认值；放弃只撤销本次输出配置修改，已自动保存的项目信息会保留。</AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>返回继续编辑</AlertDialogCancel>
                        <AlertDialogAction onClick={() => {
                            setOutputState({dirty: false, saving: false});
                            setSettingsOpen(false);
                        }}>放弃输出修改</AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
        </WorkspaceUnavailableContext>
    );
}
